/**
 * Retry utility with exponential backoff
 *
 * Wraps p-retry for consistent retry behavior across the codebase.
 * Provides a stable interface for concurrency.ts and other consumers.
 *
 * @module resiliency/retry
 */

import pRetry, { AbortError } from "p-retry";

export { AbortError };

export interface RetryOptions {
	/** Maximum number of retry attempts (not including initial attempt) */
	maxAttempts: number;
	/** Base delay in milliseconds between retries */
	baseDelayMs: number;
	/** Maximum delay cap in milliseconds (default: 30000) */
	maxDelayMs?: number;
	/** Add random jitter to prevent thundering herd (default: false) */
	jitter?: boolean;
	/** Callback invoked before each retry attempt */
	onRetry?: (error: Error, attempt: number) => void;
	/** Predicate to determine if an error should trigger a retry */
	shouldRetry?: (error: Error) => boolean;
}

/**
 * Preset retry configurations for common scenarios
 */
export const RetryPresets = {
	/** Fast retries for network requests (max 5s delay) */
	network: {
		maxAttempts: 3,
		baseDelayMs: 1000,
		maxDelayMs: 5000,
		jitter: true,
	} as RetryOptions,

	/** Medium retries for API calls (max 30s delay) */
	api: {
		maxAttempts: 5,
		baseDelayMs: 2000,
		maxDelayMs: 30000,
		jitter: true,
	} as RetryOptions,

	/** Aggressive retries for critical operations (max 1min delay) */
	critical: {
		maxAttempts: 10,
		baseDelayMs: 1000,
		maxDelayMs: 60000,
		jitter: true,
	} as RetryOptions,

	/** Quick retries for fast operations (max 2s delay) */
	fast: {
		maxAttempts: 3,
		baseDelayMs: 100,
		maxDelayMs: 2000,
		jitter: false,
	} as RetryOptions,
} as const;

/**
 * Execute an async operation with retry logic and exponential backoff
 *
 * Uses p-retry under the hood for battle-tested retry behavior.
 *
 * @param operation - Async function to execute
 * @param options - Retry configuration options
 * @returns Result of the operation
 * @throws Last error if all retry attempts fail
 *
 * @example
 * ```typescript
 * // Basic usage with preset
 * const result = await withRetry(
 *   async () => fetch('https://api.example.com/data'),
 *   RetryPresets.network
 * );
 *
 * // With custom options and retry callback
 * const result = await withRetry(
 *   async () => processData(),
 *   {
 *     maxAttempts: 5,
 *     baseDelayMs: 100,
 *     jitter: true,
 *     onRetry: (error, attempt) => {
 *       logger.warn(`Retry attempt ${attempt}`, { error });
 *     }
 *   }
 * );
 * ```
 */
export async function withRetry<T>(operation: () => Promise<T>, options: RetryOptions): Promise<T> {
	const { maxAttempts, baseDelayMs, maxDelayMs = 30000, jitter = false, onRetry, shouldRetry } = options;

	return pRetry(operation, {
		retries: maxAttempts,
		minTimeout: baseDelayMs,
		maxTimeout: maxDelayMs,
		randomize: jitter,
		onFailedAttempt: (error) => {
			// Check if we should retry this error
			if (shouldRetry && !shouldRetry(error)) {
				throw error; // Don't retry, rethrow immediately
			}

			if (onRetry) {
				onRetry(error, error.attemptNumber);
			}
		},
	});
}

/**
 * Calculate exponential backoff delay with optional jitter
 *
 * Formula: min(baseMs * 2^(attempt - 1), maxMs) [+ jitter]
 *
 * @param attempt - Current attempt number (1-based)
 * @param baseMs - Base delay in milliseconds
 * @param maxMs - Maximum delay cap
 * @param jitter - Whether to add random jitter (0-100% of calculated delay)
 * @returns Delay in milliseconds
 */
export function calculateBackoff(attempt: number, baseMs: number, maxMs: number, jitter: boolean): number {
	// Exponential backoff: baseMs * 2^(attempt - 1)
	const exponential = baseMs * 2 ** (attempt - 1);

	// Cap at maximum delay
	const capped = Math.min(exponential, maxMs);

	// Add jitter if enabled (random 0-100% of delay)
	if (jitter) {
		const jitterAmount = Math.random() * capped;
		return capped + jitterAmount;
	}

	return capped;
}
