import { LRUCache } from "lru-cache";
import { logger } from "../logging/logger";

type CacheValue = string | number | boolean | symbol | bigint | object;

// Configuration with safe defaults
export const cacheDefaults = {
	mcp: {
		cache: {
			maxEntries: 500,
			ttlMs: 60 * 60 * 1000, // 1 hour default
		},
	},
	dashboard: {
		cache: {
			maxEntries: 1000,
			defaultTtlMs: 5 * 60 * 1000, // 5 minutes default for dashboard data
		},
	},
} as const;

export const docCache = new LRUCache<string, CacheValue>({
	max: cacheDefaults.mcp.cache.maxEntries,
	ttl: cacheDefaults.mcp.cache.ttlMs,
	allowStale: true,
	updateAgeOnGet: true,
});

/**
 * Clear all doc cache entries.
 * Use in test teardown to prevent state leakage across tests.
 */
export function clearDocCache(): void {
	docCache.clear();
}

export const dashboardCache = new LRUCache<string, CacheValue>({
	max: cacheDefaults.dashboard.cache.maxEntries,
	ttl: cacheDefaults.dashboard.cache.defaultTtlMs,
	allowStale: true,
	updateAgeOnGet: true,
});

/**
 * Enhanced cache function with configurable TTL
 * @param key - Cache key
 * @param fetcher - Function to fetch data if not in cache
 * @param ttlMs - Optional TTL in milliseconds (overrides default)
 */
export async function getLibraryDocsCached<T extends CacheValue>(
	key: string,
	fetcher: () => Promise<T>,
	ttlMs?: number,
): Promise<T> {
	// Check cache first
	const hit = docCache.get(key);
	if (hit) {
		logger.debug(`Cache hit for key: ${key}`);
		return hit as T;
	}

	// Fetch and cache result
	try {
		logger.debug(`Cache miss for key: ${key}, fetching data`);
		const value = await fetcher();

		// Set with custom TTL if provided
		if (ttlMs) {
			docCache.set(key, value, { ttl: ttlMs });
		} else {
			docCache.set(key, value);
		}

		return value;
	} catch (error: unknown) {
		logger.error({ error }, `Failed to fetch data for cache key: ${key}`);
		throw error;
	}
}

/**
 * Cache with hinting support for tools that accept cache parameters
 */
export async function getLibraryDocsCachedWithHint<T extends CacheValue>(
	cacheKey: string | undefined,
	ttlMs: number | undefined,
	fetcher: () => Promise<T>,
): Promise<T> {
	// If cache key is provided, use caching
	if (cacheKey) {
		return await getLibraryDocsCached<T>(cacheKey, fetcher, ttlMs);
	}

	// Otherwise, fetch directly
	return await fetcher();
}

/**
 * Dashboard cache function with configurable TTL
 * @param key - Cache key (should include userId for isolation)
 * @param fetcher - Function to fetch data if not in cache
 * @param ttlMs - Optional TTL in milliseconds (default: 5 minutes)
 */
export async function getDashboardCached<T extends CacheValue>(
	key: string,
	fetcher: () => Promise<T>,
	ttlMs?: number,
): Promise<T> {
	// Check cache first
	const hit = dashboardCache.get(key);
	if (hit) {
		logger.debug(`Dashboard cache hit for key: ${key}`);
		return hit as T;
	}

	// Fetch and cache result
	try {
		logger.debug(`Dashboard cache miss for key: ${key}, fetching data`);
		const value = await fetcher();

		// Set with custom TTL if provided, otherwise use default
		dashboardCache.set(key, value, { ttl: ttlMs ?? cacheDefaults.dashboard.cache.defaultTtlMs });

		return value;
	} catch (error: unknown) {
		logger.error({ error }, `Failed to fetch dashboard data for cache key: ${key}`);
		throw error;
	}
}

/**
 * Invalidate dashboard cache entries by pattern
 * Useful when data changes and cache needs refreshing
 * @param pattern - String pattern to match keys (simple includes check)
 */
export function invalidateDashboardCache(pattern: string): void {
	const keysToDelete: string[] = [];

	for (const key of dashboardCache.keys()) {
		if (key.includes(pattern)) {
			keysToDelete.push(key);
		}
	}

	for (const key of keysToDelete) {
		dashboardCache.delete(key);
	}

	logger.info(`Invalidated ${keysToDelete.length} dashboard cache entries matching pattern: ${pattern}`);
}
