import CircuitBreaker from "opossum";
import { logger } from "../logging/logger";

/**
 * Sanitize error messages to remove sensitive data before logging
 *
 * Redacts common patterns that may contain credentials or sensitive info:
 * - API keys, tokens, passwords
 * - Bearer tokens in headers
 * - Connection strings
 */
function sanitizeError(error: unknown): string {
	const message = error instanceof Error ? error.message : String(error);
	return message
		.replace(/api[_-]?key[=:]\s*["']?\S+["']?/gi, "api_key=[REDACTED]")
		.replace(/token[=:]\s*["']?\S+["']?/gi, "token=[REDACTED]")
		.replace(/password[=:]\s*["']?\S+["']?/gi, "password=[REDACTED]")
		.replace(/bearer\s+\S+/gi, "Bearer [REDACTED]")
		.replace(/authorization[=:]\s*["']?\S+["']?/gi, "authorization=[REDACTED]")
		.replace(/secret[=:]\s*["']?\S+["']?/gi, "secret=[REDACTED]")
		.replace(/credential[s]?[=:]\s*["']?\S+["']?/gi, "credentials=[REDACTED]");
}

// Default configuration for resilience patterns
export const resilienceDefaults = {
	mcp: {
		timeoutMs: 5000,
		maxConcurrent: 4,
		retry: { maxAttempts: 2, baseDelayMs: 250, maxDelayMs: 1500, jitter: true },
		circuit: {
			enabled: true,
			errorThresholdPercentage: 50,
			volumeThreshold: 10,
			timeoutMs: 5000,
			resetMs: 30000,
			rollingCountMs: 60000,
			rollingCountBuckets: 6,
		},
		batch: {
			size: 5,
			maxWaitMs: 150,
		},
	},
} as const;

type ToolFn<I, O> = (input: I) => Promise<O>;

interface BreakerConfig {
	enabled?: boolean;
	errorThresholdPercentage: number;
	volumeThreshold: number;
	timeoutMs: number;
	resetMs: number;
	rollingCountMs: number;
	rollingCountBuckets: number;
}

// Store circuit breakers by tool name  -  use any[] to avoid covariant cast on retrieval
// biome-ignore lint/suspicious/noExplicitAny: heterogeneous cache keyed by tool name; cast at retrieval site
const circuitBreakers = new Map<string, CircuitBreaker<any[], any>>();

export function withBreaker<I, O>(
	toolName: string,
	fn: ToolFn<I, O>,
	cfg: BreakerConfig = resilienceDefaults.mcp.circuit,
) {
	// Get or create circuit breaker for this tool
	if (!circuitBreakers.has(toolName)) {
		const br = new CircuitBreaker<[I], O>(async (input: I) => fn(input), {
			timeout: cfg.timeoutMs,
			errorThresholdPercentage: cfg.errorThresholdPercentage,
			resetTimeout: cfg.resetMs,
			rollingCountTimeout: cfg.rollingCountMs,
			rollingCountBuckets: cfg.rollingCountBuckets,
			volumeThreshold: cfg.volumeThreshold,
		});

		// Circuit state change events with stats
		br.on("open", () => {
			logger.warn(`Circuit breaker opened for tool: ${toolName}`, {
				tool: toolName,
				state: "open",
				stats: br.stats,
			});
		});

		br.on("halfOpen", () => {
			logger.warn(`Circuit breaker half-open for tool: ${toolName}`, {
				tool: toolName,
				state: "half-open",
				stats: br.stats,
			});
		});

		br.on("close", () => {
			logger.info(`Circuit breaker closed for tool: ${toolName}`, {
				tool: toolName,
				state: "closed",
				stats: br.stats,
			});
		});

		// Success/failure telemetry events
		br.on("success", () => {
			logger.debug(`Circuit breaker success for tool: ${toolName}`, {
				tool: toolName,
				event: "success",
				successes: br.stats.successes,
				failures: br.stats.failures,
			});
		});

		br.on("failure", (error) => {
			logger.warn(`Circuit breaker failure for tool: ${toolName}`, {
				tool: toolName,
				event: "failure",
				error: sanitizeError(error),
				successes: br.stats.successes,
				failures: br.stats.failures,
			});
		});

		// Additional monitoring events
		br.on("timeout", () => {
			logger.warn(`Circuit breaker timeout for tool: ${toolName}`, {
				tool: toolName,
				event: "timeout",
				timeoutMs: cfg.timeoutMs,
			});
		});

		br.on("reject", () => {
			logger.warn(`Circuit breaker rejected call for tool: ${toolName}`, {
				tool: toolName,
				event: "reject",
				state: br.opened ? "open" : br.halfOpen ? "half-open" : "closed",
			});
		});

		circuitBreakers.set(toolName, br);
	}

	const br = circuitBreakers.get(toolName) as CircuitBreaker<[I], O> | undefined;
	if (!br) {
		throw new Error(`Circuit breaker not found for tool: ${toolName}`);
	}
	return (input: I) => br.fire(input) as Promise<O>;
}

export function getCircuitBreakerState(toolName: string) {
	const br = circuitBreakers.get(toolName);
	if (!br) {
		return null;
	}
	return {
		isOpen: br.opened,
		isHalfOpen: br.halfOpen,
		isClosed: br.closed,
	};
}

/**
 * Clear all circuit breakers.
 * Use in test teardown to prevent state leakage across tests.
 */
export function clearCircuitBreakers(): void {
	circuitBreakers.clear();
}
