import pino from "pino";

/**
 * Check if running in MCP quiet mode (suppress all non-error output for MCP stdio)
 * When MCP_QUIET=1, only fatal errors are logged to avoid corrupting MCP protocol
 */
const MCP_QUIET = process.env.MCP_QUIET === "1" || process.env.MCP_QUIET === "true";

// Copying logic from core logger
const isProduction = process.env.NODE_ENV === "production";
const isTest = process.env.NODE_ENV === "test" || process.env.VITEST === "true";
const isVSCodeExtension = process.env.VSCODE_EXTENSION === "true";
// Next.js detection - pino-pretty worker threads don't work with Next.js bundling
const isNextJS =
	typeof process.env.NEXT_RUNTIME !== "undefined" || typeof process.env.__NEXT_PRIVATE_ORIGIN !== "undefined";
// Bundled mode detection - pino-pretty worker threads don't work in bundled code
// This happens when running as MCPB, VSCode extension, or other bundled contexts
const isBundled =
	typeof process.env.VREKO_BUNDLED !== "undefined" ||
	// Check if we're running from a bundled location (dist/server with no source)
	(typeof __dirname === "string" && !__dirname.includes("node_modules") && !__dirname.includes("packages/"));

// Service name for log prefix (helps with terminal multiplexer clarity)
const serviceName = process.env.SERVICE_NAME || process.env.npm_package_name || "app";

// Define redaction paths for sensitive data
const redactPaths = [
	"user.email",
	"user.password",
	"apiKey",
	"session.token",
	"req.headers.authorization",
	"auth.*.password",
	"config.*.secret",
	"env.*",
	"password",
	"token",
	"secret",
	"authorization",
	"cookie",
	"*.password",
	"*.token",
	"*.apiKey",
	"*.secret",
	"*.authorization",
	"*.cookie",
	"*.path",
	"*.file",
	"*.filePath",
];

/**
 * Mixin function to inject OTel trace context into every log line
 * This is a fallback/supplement to PinoInstrumentation
 * Works even if OTel isn't initialized (returns empty strings)
 */
function traceContextMixin(): Record<string, string> {
	// Try to get active span from OTel context
	// This is safe - if OTel isn't loaded, we just return empty strings
	try {
		// Dynamic import to avoid hard dependency on OTel
		// eslint-disable-next-line @typescript-eslint/no-var-requires
		const api = require("@opentelemetry/api");
		const span = api.trace.getSpan(api.context.active());
		if (span) {
			const ctx = span.spanContext();
			return {
				trace_id: ctx.traceId,
				span_id: ctx.spanId,
			};
		}
	} catch {
		// OTel not available, skip trace context
	}
	return {};
}

// Use stderr instead of stdout to avoid polluting stdout (critical for MCP)
// VSCode extensions also typically log to output channels or stderr
const pinoLogger = pino(
	{
		// When MCP_QUIET=1, set level to 'silent' to suppress all output
		level: MCP_QUIET ? "silent" : process.env.LOG_LEVEL || "info",
		redact: {
			paths: redactPaths,
			censor: "[REDACTED]",
		},
		// Add service name as base context for terminal multiplexer clarity
		base: { service: serviceName },
		// Inject trace context into every log line
		mixin: traceContextMixin,
		// Only use transport in non-production AND non-VSCode AND non-Next.js AND non-test environments
		// pino-pretty uses worker threads which fail in Next.js bundled contexts and vitest
		// Also disable in bundled mode (MCPB) where worker threads don't work
		...(isProduction || isTest || isVSCodeExtension || MCP_QUIET || isNextJS || isBundled
			? {}
			: {
					transport: {
						target: "pino-pretty",
						options: {
							colorize: true,
							translateTime: "SYS:HH:MM:ss.l",
							ignore: "pid,hostname,service",
							// Show service name in message prefix for terminal clarity
							messageFormat: "[{service}] {msg}",
							// Include trace context in output - this is your "local Grafana"
							// trace_id will appear inline when OTel is active
							include: "level,time,trace_id,span_id",
							// Single line for better terminal readability
							singleLine: true,
							// Custom colors for level differentiation
							levelColors: {
								trace: "gray",
								debug: "cyan",
								info: "green",
								warn: "yellow",
								error: "red",
								fatal: "bgRed",
							},
						},
					},
				}),
	},
	pino.destination({ fd: 2 }), // fd 2 = stderr
);

// Export strict interface to enforce consistent usage
// Supports both patterns: ("message", { meta }) and ({ meta }, "message")
export const logger = {
	debug: (messageOrObj: string | Record<string, unknown>, metaOrMsg?: Record<string, unknown> | string): void => {
		if (typeof messageOrObj === "string" && (!metaOrMsg || typeof metaOrMsg === "object")) {
			// Pattern: ("message") or ("message", { meta })
			if (metaOrMsg) {
				pinoLogger.debug(metaOrMsg, messageOrObj);
			} else {
				pinoLogger.debug(messageOrObj);
			}
		} else if (typeof messageOrObj === "object" && typeof metaOrMsg === "string") {
			// Pattern: ({ meta }, "message") - Pino native
			pinoLogger.debug(messageOrObj, metaOrMsg);
		}
	},
	info: (messageOrObj: string | Record<string, unknown>, metaOrMsg?: Record<string, unknown> | string): void => {
		if (typeof messageOrObj === "string" && (!metaOrMsg || typeof metaOrMsg === "object")) {
			// Pattern: ("message") or ("message", { meta })
			if (metaOrMsg) {
				pinoLogger.info(metaOrMsg, messageOrObj);
			} else {
				pinoLogger.info(messageOrObj);
			}
		} else if (typeof messageOrObj === "object" && typeof metaOrMsg === "string") {
			// Pattern: ({ meta }, "message") - Pino native
			pinoLogger.info(messageOrObj, metaOrMsg);
		}
	},
	warn: (messageOrObj: string | Record<string, unknown>, metaOrMsg?: Record<string, unknown> | string): void => {
		if (typeof messageOrObj === "string" && (!metaOrMsg || typeof metaOrMsg === "object")) {
			// Pattern: ("message") or ("message", { meta })
			if (metaOrMsg) {
				pinoLogger.warn(metaOrMsg, messageOrObj);
			} else {
				pinoLogger.warn(messageOrObj);
			}
		} else if (typeof messageOrObj === "object" && typeof metaOrMsg === "string") {
			// Pattern: ({ meta }, "message") - Pino native
			pinoLogger.warn(messageOrObj, metaOrMsg);
		}
	},
	error: (
		messageOrObj: string | Record<string, unknown> | Error,
		metaOrMsg?: Record<string, unknown> | Error | string,
	): void => {
		if (typeof messageOrObj === "string" && (!metaOrMsg || typeof metaOrMsg !== "string")) {
			// Pattern: ("message") or ("message", { meta }) or ("message", error)
			if (metaOrMsg) {
				pinoLogger.error(metaOrMsg, messageOrObj);
			} else {
				pinoLogger.error(messageOrObj);
			}
		} else if (typeof messageOrObj === "object" && typeof metaOrMsg === "string") {
			// Pattern: ({ meta }, "message") or (error, "message") - Pino native
			pinoLogger.error(messageOrObj, metaOrMsg);
		}
	},
	// Child method for creating scoped loggers
	child: (bindings: Record<string, unknown>) => {
		const childLogger = pinoLogger.child(bindings);
		return {
			debug: (
				messageOrObj: string | Record<string, unknown>,
				metaOrMsg?: Record<string, unknown> | string,
			): void => {
				if (typeof messageOrObj === "string" && (!metaOrMsg || typeof metaOrMsg === "object")) {
					if (metaOrMsg) {
						childLogger.debug(metaOrMsg, messageOrObj);
					} else {
						childLogger.debug(messageOrObj);
					}
				} else if (typeof messageOrObj === "object" && typeof metaOrMsg === "string") {
					childLogger.debug(messageOrObj, metaOrMsg);
				}
			},
			info: (
				messageOrObj: string | Record<string, unknown>,
				metaOrMsg?: Record<string, unknown> | string,
			): void => {
				if (typeof messageOrObj === "string" && (!metaOrMsg || typeof metaOrMsg === "object")) {
					if (metaOrMsg) {
						childLogger.info(metaOrMsg, messageOrObj);
					} else {
						childLogger.info(messageOrObj);
					}
				} else if (typeof messageOrObj === "object" && typeof metaOrMsg === "string") {
					childLogger.info(messageOrObj, metaOrMsg);
				}
			},
			warn: (
				messageOrObj: string | Record<string, unknown>,
				metaOrMsg?: Record<string, unknown> | string,
			): void => {
				if (typeof messageOrObj === "string" && (!metaOrMsg || typeof metaOrMsg === "object")) {
					if (metaOrMsg) {
						childLogger.warn(metaOrMsg, messageOrObj);
					} else {
						childLogger.warn(messageOrObj);
					}
				} else if (typeof messageOrObj === "object" && typeof metaOrMsg === "string") {
					childLogger.warn(messageOrObj, metaOrMsg);
				}
			},
			error: (
				messageOrObj: string | Record<string, unknown> | Error,
				metaOrMsg?: Record<string, unknown> | Error | string,
			): void => {
				if (typeof messageOrObj === "string" && (!metaOrMsg || typeof metaOrMsg !== "string")) {
					if (metaOrMsg) {
						childLogger.error(metaOrMsg, messageOrObj);
					} else {
						childLogger.error(messageOrObj);
					}
				} else if (typeof messageOrObj === "object" && typeof metaOrMsg === "string") {
					childLogger.error(messageOrObj, metaOrMsg);
				}
			},
			level: childLogger.level,
			child: (nestedBindings: Record<string, unknown>) => logger.child({ ...bindings, ...nestedBindings }),
		};
	},
};

// Re-export the logger interface and types from contracts
export type { Logger } from "@vreko/contracts";
export { LogLevel } from "@vreko/contracts";
